/*
 * Servo Sweep — Sweep servo 0 to 180 degrees
 */

#include <Servo.h>

Servo myServo;
int angle = 0;
int step = 2;

void setup() {
  myServo.attach(9);
  Serial.begin(115200);
  Serial.println("Servo sweep started");
}

void loop() {
  myServo.write(angle);
  Serial.print("Angle: ");
  Serial.println(angle);

  angle += step;
  if (angle >= 180 || angle <= 0) {
    step = -step;
    delay(200);
  }
  delay(15);
}
